import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CmvPqeTF.js";const _=JSON.parse('{"title":"数据存储与加密","description":"","frontmatter":{},"headers":[],"relativePath":"dev/storage-crypto.md","filePath":"dev/storage-crypto.md","lastUpdated":1788361893000}'),r={name:"dev/storage-crypto.md"};function c(n,t,s,i,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据存储与加密" tabindex="-1">数据存储与加密 <a class="header-anchor" href="#数据存储与加密" aria-label="Permalink to &quot;数据存储与加密&quot;">​</a></h1><p>vShell 的全部持久化都在本机：一个 SQLite 数据库 + 一个加密密钥文件。没有云端、没有遥测。</p><hr><h2 id="_1-文件位置-macos" tabindex="-1">1. 文件位置（macOS） <a class="header-anchor" href="#_1-文件位置-macos" aria-label="Permalink to &quot;1. 文件位置（macOS）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>路径</th><th>内容</th></tr></thead><tbody><tr><td>数据库</td><td><code>~/Library/Application Support/vshell/vshell.db</code></td><td>连接 / 分组 / 快捷命令 / 端口转发</td></tr><tr><td>加密密钥</td><td><code>~/Library/Application Support/vshell/.enc_key</code></td><td>base64 的 32 字节 AES 密钥（目录 0700、文件 0600）</td></tr></tbody></table><p>路径由 <code>os.UserConfigDir()</code> 推导，Linux 下为 <code>~/.config/vshell/</code>，Windows 为 <code>%AppData%\\vshell\\</code>。</p><h2 id="_2-sqlite-配置" tabindex="-1">2. SQLite 配置 <a class="header-anchor" href="#_2-sqlite-配置" aria-label="Permalink to &quot;2. SQLite 配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>驱动</td><td><code>modernc.org/sqlite</code></td><td>纯 Go，<strong>无 CGO</strong>（红线 6）</td></tr><tr><td>日志模式</td><td>WAL</td><td>DSN <code>_pragma=journal_mode(WAL)</code></td></tr><tr><td>外键</td><td>开启</td><td><code>_pragma=foreign_keys(1)</code></td></tr><tr><td>连接数</td><td><code>SetMaxOpenConns(1)</code></td><td>单连接串行化，规避 SQLite 锁问题</td></tr></tbody></table><p><code>db.DB</code> 为 <code>sync.Once</code> 单例，内嵌 <code>*sql.DB</code> 并持有 <code>CryptoService</code>。应用退出时统一 <code>Close</code>。</p><h2 id="_3-表结构" tabindex="-1">3. 表结构 <a class="header-anchor" href="#_3-表结构" aria-label="Permalink to &quot;3. 表结构&quot;">​</a></h2><h3 id="groups" tabindex="-1">groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;groups&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>类型</th><th>约束</th></tr></thead><tbody><tr><td>id</td><td>TEXT</td><td>PRIMARY KEY</td></tr><tr><td>name</td><td>TEXT</td><td>NOT NULL</td></tr><tr><td>parent_id</td><td>TEXT</td><td>REFERENCES groups(id) ON DELETE <strong>CASCADE</strong></td></tr><tr><td>sort_order</td><td>INTEGER</td><td>DEFAULT 0</td></tr><tr><td>created_at / updated_at</td><td>DATETIME</td><td>DEFAULT CURRENT_TIMESTAMP</td></tr></tbody></table><h3 id="connections" tabindex="-1">connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;connections&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>类型</th><th>约束 / 说明</th></tr></thead><tbody><tr><td>id</td><td>TEXT</td><td>PRIMARY KEY</td></tr><tr><td>group_id</td><td>TEXT</td><td>REFERENCES groups(id) ON DELETE <strong>SET NULL</strong></td></tr><tr><td>name / host / username</td><td>TEXT</td><td>NOT NULL</td></tr><tr><td>port</td><td>INTEGER</td><td>DEFAULT 22</td></tr><tr><td>auth_type</td><td>TEXT</td><td>NOT NULL（password / private_key / agent / interactive）</td></tr><tr><td>password / private_key / key_passphrase</td><td>TEXT</td><td><strong>AES-256-GCM 密文</strong></td></tr><tr><td>key_name</td><td>TEXT</td><td>托管密钥名（相对 <code>~/.ssh</code>）</td></tr><tr><td>proxy_type / proxy_addr / jump_host_id</td><td>TEXT</td><td>预留，未启用</td></tr><tr><td>upload_path</td><td>TEXT</td><td>DEFAULT &#39;/&#39;</td></tr><tr><td>default_cmd</td><td>TEXT</td><td>预留</td></tr><tr><td>sort_order / color / last_used_at</td><td>—</td><td>color 等字段暂无 UI</td></tr><tr><td>created_at / updated_at</td><td>DATETIME</td><td>DEFAULT CURRENT_TIMESTAMP</td></tr></tbody></table><h3 id="quick-commands-port-forwards" tabindex="-1">quick_commands / port_forwards <a class="header-anchor" href="#quick-commands-port-forwards" aria-label="Permalink to &quot;quick_commands / port_forwards&quot;">​</a></h3><p><code>quick_commands(id, name, command NOT NULL, connection_id, sort_order, …)</code> 与 <code>port_forwards(id, name, connection_id NOT NULL, type NOT NULL, local_host, local_port, remote_host, remote_port, auto_start DEFAULT 0)</code>。两者的 <code>connection_id</code> <strong>未设外键</strong>（手工删除连接记录不会级联）。</p><h3 id="迁移机制" tabindex="-1">迁移机制 <a class="header-anchor" href="#迁移机制" aria-label="Permalink to &quot;迁移机制&quot;">​</a></h3><p>无版本表：每次启动重放 <code>CREATE TABLE IF NOT EXISTS</code> + 容错的 <code>ALTER TABLE ADD COLUMN</code>（列已存在时忽略错误）。适合当前规模；引入破坏性变更前需要升级为版本化迁移。</p><h2 id="_4-aes-256-gcm-凭证加密-internal-crypto" tabindex="-1">4. AES-256-GCM 凭证加密（<code>internal/crypto</code>） <a class="header-anchor" href="#_4-aes-256-gcm-凭证加密-internal-crypto" aria-label="Permalink to &quot;4. AES-256-GCM 凭证加密（\`internal/crypto\`）&quot;">​</a></h2><h3 id="_4-1-密钥派生" tabindex="-1">4.1 密钥派生 <a class="header-anchor" href="#_4-1-密钥派生" aria-label="Permalink to &quot;4.1 密钥派生&quot;">​</a></h3><p>按优先级：</p><ol><li>环境变量 <code>VSHELL_ENCRYPTION_KEY</code>（base64，须 32 字节）——便于备份 / 迁移场景</li><li>已存在的 <code>.enc_key</code> 文件</li><li>首次运行用 <code>crypto/rand</code> 生成 32 字节随机密钥写入 <code>.enc_key</code></li></ol><blockquote><p>注意：密钥<strong>不是</strong>机器绑定，也不入 Keychain——就是配置目录里的文件。备份整个 <code>vshell/</code> 目录（含 <code>.enc_key</code>）即可在其他机器解密；只拷数据库则无法解密。</p></blockquote><h3 id="_4-2-加解密流程" tabindex="-1">4.2 加解密流程 <a class="header-anchor" href="#_4-2-加解密流程" aria-label="Permalink to &quot;4.2 加解密流程&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Encrypt(plain)                          Decrypt(cipher)</span></span>
<span class="line"><span>  nonce = rand(12)                         raw   = base64decode(cipher)</span></span>
<span class="line"><span>  ct    = AES-256-GCM.Seal(nonce,          nonce = raw[:12]</span></span>
<span class="line"><span>            key, nonce, plain)             pt    = GCM.Open(key, nonce,</span></span>
<span class="line"><span>  return base64(nonce ‖ ct)                       raw[12:])   // 认证校验失败即报错</span></span></code></pre></div><ul><li>空字符串直接存空（不加密）</li><li>GCM 自带完整性认证，被篡改的密文解密时报错</li></ul><h3 id="_4-3-哪些字段加密" tabindex="-1">4.3 哪些字段加密 <a class="header-anchor" href="#_4-3-哪些字段加密" aria-label="Permalink to &quot;4.3 哪些字段加密&quot;">​</a></h3><p>仅 <code>connections</code> 表的 <code>password</code> / <code>private_key</code> / <code>key_passphrase</code> 三列。分组名、命令、端口转发等均为明文（不含凭证）。</p><h3 id="_4-4-读写路径" tabindex="-1">4.4 读写路径 <a class="header-anchor" href="#_4-4-读写路径" aria-label="Permalink to &quot;4.4 读写路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>流程</th></tr></thead><tbody><tr><td>保存连接</td><td><code>CreateConnection</code> / <code>UpdateConnection</code> 先 <code>Encrypt</code> 再入库；更新时敏感字段留空则保留旧密文</td></tr><tr><td>列表</td><td><code>ListConnections</code> SELECT 显式排除三列，<strong>密文不出后端</strong></td></tr><tr><td>表单回显</td><td><code>GetPassword</code> / <code>GetPrivateKey</code> / <code>GetKeyPassphrase</code> 解密返回</td></tr><tr><td>建立连接</td><td><code>buildSSHConfig</code> 取全列解密后用于认证</td></tr><tr><td>密钥删除保护</td><td><code>GetSSHKeyUsage</code> 除按 <code>key_name</code> 匹配外，解密各连接私钥逐字节比对内容</td></tr></tbody></table><h2 id="_5-数据安全边界-如实说明" tabindex="-1">5. 数据安全边界（如实说明） <a class="header-anchor" href="#_5-数据安全边界-如实说明" aria-label="Permalink to &quot;5. 数据安全边界（如实说明）&quot;">​</a></h2><ul><li>SSH <code>HostKeyCallback</code> 当前为 <code>InsecureIgnoreHostKey()</code>，不校验主机指纹（无 known_hosts 集成）</li><li><code>.enc_key</code> 与数据库同目录，防不了本机已被入侵的攻击者，防的是数据库文件单独泄露</li><li>敏感字段明文仅存在于后端内存与加密前的表单提交中</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./architecture.html">架构总览</a></li><li><a href="./../guide/connections.html">连接与分组管理</a></li></ul>`,35)])])}const u=e(r,[["render",c]]);export{_ as __pageData,u as default};
